local ThresherMaker = {}
local PRODUCTS = {
    simple_wood_thresher = { name = "Preprost leseni mlatilni stroj", woodCost = 5, ironCost = 2, ropeCost = 1, time = 6, cost = 200, food = 28, happiness = 1, description = "Preprost leseni mlatilni stroj za mlatitev." },
    iron_drum_thresher = { name = "Železnobobenski mlatilni stroj", woodCost = 4, ironCost = 3, ropeCost = 1, time = 9, cost = 480, food = 42, happiness = 2, prestige = 2, description = "Železnobobenski mlatilni stroj za trgovce." },
    silver_geared_thresher = { name = "Srebrnozobčani mlatilni stroj", woodCost = 4, silverCost = 1, ironCost = 3, ropeCost = 1, time = 13, cost = 1100, food = 58, happiness = 2, prestige = 6, description = "Srebrnozobčani mlatilni stroj za plemiče." },
    gold_trimmed_thresher = { name = "Zlatookrasni mlatilni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, ropeCost = 1, time = 17, cost = 2500, food = 75, happiness = 3, prestige = 14, description = "Zlatookrasni mlatilni stroj za visoke plemiče." },
    jewel_set_thresher = { name = "Draguljasta mlatilni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, ropeCost = 1, jewelCost = 1, time = 21, cost = 5400, food = 90, happiness = 5, prestige = 27, description = "Mlatilni stroj z draguljem za visoko plemstvo." },
    royal_grand_thresher = { name = "Kraljevski veliki mlatilni stroj", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 3, ropeCost = 1, jewelCost = 2, pearlCost = 2, time = 28, cost = 11500, food = 100, happiness = 12, prestige = 58, description = "Veliki kraljevski mlatilni stroj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    thresher_workshop = { name = "Mlatilna delavnica", cost = { gold = 300, wood = 180, stone = 140, iron = 8, rope = 4 }, upkeep = 7, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 1100, wood = 320, stone = 280, silver = 6, iron = 8 }, upkeep = 25, qualityBonus = 18 },
    master_thresher_atelier = { name = "Mojstrski mlatilni atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
ThresherMaker.woodStock = 22; ThresherMaker.ironStock = 14; ThresherMaker.ropeStock = 8; ThresherMaker.silverStock = 6; ThresherMaker.goldStock = 6; ThresherMaker.jewelStock = 4; ThresherMaker.pearlStock = 4
ThresherMaker.productStock = {}; ThresherMaker.buildings = {}; ThresherMaker.maker = nil; ThresherMaker.activeMaking = {}; ThresherMaker.totalProducts = 0; ThresherMaker.dayTimer = 0
function ThresherMaker.init() ThresherMaker.woodStock=22; ThresherMaker.ironStock=14; ThresherMaker.ropeStock=8; ThresherMaker.silverStock=6; ThresherMaker.goldStock=6; ThresherMaker.jewelStock=4; ThresherMaker.pearlStock=4; ThresherMaker.productStock={}; ThresherMaker.buildings={}; ThresherMaker.maker=nil; ThresherMaker.activeMaking={}; ThresherMaker.totalProducts=0; ThresherMaker.dayTimer=0; print("[ThresherMaker] Royal Thresher Maker System initialized (6 products, 4 buildings)") end
function ThresherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ThresherMaker.maker={name=n or ("Mlatilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlatilnikar najet: %s (spretnost: %d)",ThresherMaker.maker.name,s),"success") end; return true end
function ThresherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ThresherMaker.build(id) local ok,e=ThresherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ThresherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ThresherMaker.getQualityBonus() local b=0; for _,bd in ipairs(ThresherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ThresherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ThresherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ThresherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.ropeCost and ThresherMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and ThresherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ThresherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ThresherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ThresherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ThresherMaker.buildings==0 then return false,"Potrebna mlatilna delavnica" end; if not ThresherMaker.maker then return false,"Potreben mlatilnikar" end; return true end
function ThresherMaker.make(pt,qty) qty=qty or 1; local ok,e=ThresherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ThresherMaker.woodStock=ThresherMaker.woodStock-d.woodCost*qty end; if d.ironCost then ThresherMaker.ironStock=ThresherMaker.ironStock-d.ironCost*qty end; if d.ropeCost then ThresherMaker.ropeStock=ThresherMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then ThresherMaker.silverStock=ThresherMaker.silverStock-d.silverCost*qty end; if d.goldCost then ThresherMaker.goldStock=ThresherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ThresherMaker.jewelStock=ThresherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ThresherMaker.pearlStock=ThresherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ThresherMaker.maker then t=math.max(1,t-math.floor(ThresherMaker.maker.skill/12)) end; table.insert(ThresherMaker.activeMaking,{id="thresher_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ThresherMaker.completeMaking(m) local q=1.0+(ThresherMaker.getQualityBonus()/100); if ThresherMaker.maker then q=q+(ThresherMaker.maker.skill/140) end; q=math.min(2.5,q); ThresherMaker.productStock[m.productType]=(ThresherMaker.productStock[m.productType] or 0)+m.quantity; ThresherMaker.totalProducts=ThresherMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ThresherMaker.maker then ThresherMaker.maker.itemsMade=ThresherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ThresherMaker.maker.skill=math.min(100,ThresherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlatilni stroj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"thresher.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function ThresherMaker.update(dt) if not _G.state then return end; ThresherMaker.dayTimer=ThresherMaker.dayTimer+dt; if ThresherMaker.dayTimer>=30 then ThresherMaker.dayTimer=0; for i=#ThresherMaker.activeMaking,1,-1 do local m=ThresherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ThresherMaker.completeMaking(m); table.remove(ThresherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ThresherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ThresherMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ThresherMaker.getStats() return {woodStock=ThresherMaker.woodStock,ironStock=ThresherMaker.ironStock,ropeStock=ThresherMaker.ropeStock,silverStock=ThresherMaker.silverStock,goldStock=ThresherMaker.goldStock,jewelStock=ThresherMaker.jewelStock,pearlStock=ThresherMaker.pearlStock,productStock=ThresherMaker.productStock,numBuildings=#ThresherMaker.buildings,hasMaker=ThresherMaker.maker~=nil,makerName=ThresherMaker.maker and ThresherMaker.maker.name or "—",makerSkill=ThresherMaker.maker and ThresherMaker.maker.skill or 0,activeMaking=#ThresherMaker.activeMaking,totalProducts=ThresherMaker.totalProducts} end
return ThresherMaker
